/// <reference types="node" />

import type { OutputFormat, Output, StrictUint8Array } from './types'

export type AesMode = 'CBC' | 'CTR' | 'GCM'

export type CipherUsage = 'encrypt' | 'decrypt'

export interface CipherOptions<F extends OutputFormat = 'uint8'> {
  data: StrictUint8Array
  nonce: StrictUint8Array
  format?: F
  additionalData?: StrictUint8Array
}

export interface AesCipher {
  encrypt<F extends OutputFormat = 'uint8'>(options: CipherOptions<F>): Promise<Output<F>>
  decrypt<F extends OutputFormat = 'uint8'>(options: CipherOptions<F>): Promise<Output<F>>
}

export function aes(mode: AesMode, key: StrictUint8Array, usage?: CipherUsage): Promise<AesCipher>

export interface AesOptions<F extends OutputFormat = 'uint8'> {
  key: StrictUint8Array
  data: StrictUint8Array
  nonce: StrictUint8Array
  format?: F
}

export interface AesGCMOptions<F extends OutputFormat = 'uint8'> extends AesOptions<F> {
  additionalData?: StrictUint8Array
}

export function encryptCBC<F extends OutputFormat = 'uint8'>(
  options: AesOptions<F>
): Promise<Output<F>>

export function decryptCBC<F extends OutputFormat = 'uint8'>(
  options: AesOptions<F>
): Promise<Output<F>>

export function encryptCTR<F extends OutputFormat = 'uint8'>(
  options: AesOptions<F>
): Promise<Output<F>>

export function decryptCTR<F extends OutputFormat = 'uint8'>(
  options: AesOptions<F>
): Promise<Output<F>>

export function encryptGCM<F extends OutputFormat = 'uint8'>(
  options: AesGCMOptions<F>
): Promise<Output<F>>

export function decryptGCM<F extends OutputFormat = 'uint8'>(
  options: AesGCMOptions<F>
): Promise<Output<F>>
